#!/usr/bin/env python3
"""Generate docs/m1-parm-inventory.md from base/renderprogs.

Scans the TNO decompiled renderprog triplets that the sync step copies
into base/renderprogs and writes one inventory document: the full prog
list, the parm list per prog, and the union of every parm name across
all progs. The union is the ground truth for the engine-side renderparm
registry.
"""

import pathlib

ROOT = pathlib.Path(__file__).resolve().parents[2]
SRC = ROOT / "base" / "renderprogs"
OUT = ROOT / "docs" / "m1-parm-inventory.md"


def main():
    parms_files = sorted(SRC.glob("*.parms"))
    progs = []
    union = {}
    for parms in parms_files:
        name = parms.stem
        lines = [line.strip() for line in parms.read_text().splitlines()]
        names = [line for line in lines if line]
        progs.append((name, names))
        for parm in names:
            union[parm] = union.get(parm, 0) + 1

    out = []
    out.append("# TNO renderprog inventory")
    out.append("")
    out.append("Generated by .github/scripts/renderprog_inventory.py from the")
    out.append("decompiled renderprogs in base/renderprogs. Reference source:")
    out.append("references/wolftno (Wolfenstein: The New Order reconstruction,")
    out.append("decompiled MachineGames/Bethesda id Tech 5 code, unlicensed).")
    out.append("")
    out.append("## Summary")
    out.append("")
    out.append("- progs: %d" % len(progs))
    out.append("- unique parm names: %d" % len(union))
    out.append("")
    out.append("## Parm union")
    out.append("")
    out.append("| parm | progs using it |")
    out.append("|---|---|")
    for parm in sorted(union):
        out.append("| %s | %d |" % (parm, union[parm]))
    out.append("")
    out.append("## Progs")
    out.append("")
    for name, names in progs:
        out.append("### %s" % name)
        out.append("")
        out.append(" ".join(names))
        out.append("")
    OUT.write_text("\n".join(out) + "\n")


if __name__ == "__main__":
    main()
